-- Follow-up query for the 746 mechanism IDs absent from the archived Gaia Archive candidate extract.
-- Run against the Gaia DR3 TAP schema. This is diagnostic only; it does not change labels or scores.
-- The formula below reproduces the companion-mass expression recorded in provenance_gaia.txt.
SELECT
  g.source_id,
  o.source_id AS nss_source_id,
  o.nss_solution_type,
  o.period,
  o.parallax,
  o.a_thiele_innes,
  o.b_thiele_innes,
  o.f_thiele_innes,
  o.g_thiele_innes,
  b.m1,
  b.m1_lower,
  b.m1_upper,
  CASE
    WHEN o.source_id IS NULL THEN 'NO_NSS_ROW'
    WHEN b.source_id IS NULL THEN 'NO_BINARY_MASSES_ROW'
    WHEN b.m1 IS NULL OR b.m1 <= 0 THEN 'NONPOSITIVE_OR_MISSING_M1'
    WHEN o.a_thiele_innes IS NULL OR o.parallax IS NULL OR o.parallax <= 0 OR o.period IS NULL OR o.period <= 0 THEN 'MISSING_OR_INVALID_ORBIT_INPUT'
    WHEN (1047.6*b.m1*(SQRT(((o.a_thiele_innes*o.a_thiele_innes+o.b_thiele_innes*o.b_thiele_innes+o.f_thiele_innes*o.f_thiele_innes+o.g_thiele_innes*o.g_thiele_innes)/2.0)+SQRT(ABS(((o.a_thiele_innes*o.a_thiele_innes+o.b_thiele_innes*o.b_thiele_innes+o.f_thiele_innes*o.f_thiele_innes+o.g_thiele_innes*o.g_thiele_innes)/2.0)*((o.a_thiele_innes*o.a_thiele_innes+o.b_thiele_innes*o.b_thiele_innes+o.f_thiele_innes*o.f_thiele_innes+o.g_thiele_innes*o.g_thiele_innes)/2.0)-(o.a_thiele_innes*o.g_thiele_innes-o.b_thiele_innes*o.f_thiele_innes)*(o.a_thiele_innes*o.g_thiele_innes-o.b_thiele_innes*o.f_thiele_innes))))/o.parallax)/POWER(b.m1*POWER(o.period/365.25,2),1.0/3.0)) >= 80 THEN 'M2_GE_80_MJUP'
    ELSE 'PASSES_ORIGINAL_JOIN_AND_M2_CUT'
  END AS archived_extract_exclusion_diagnostic,
  (1047.6*b.m1*(SQRT(((o.a_thiele_innes*o.a_thiele_innes+o.b_thiele_innes*o.b_thiele_innes+o.f_thiele_innes*o.f_thiele_innes+o.g_thiele_innes*o.g_thiele_innes)/2.0)+SQRT(ABS(((o.a_thiele_innes*o.a_thiele_innes+o.b_thiele_innes*o.b_thiele_innes+o.f_thiele_innes*o.f_thiele_innes+o.g_thiele_innes*o.g_thiele_innes)/2.0)*((o.a_thiele_innes*o.a_thiele_innes+o.b_thiele_innes*o.b_thiele_innes+o.f_thiele_innes*o.f_thiele_innes+o.g_thiele_innes*o.g_thiele_innes)/2.0)-(o.a_thiele_innes*o.g_thiele_innes-o.b_thiele_innes*o.f_thiele_innes)*(o.a_thiele_innes*o.g_thiele_innes-o.b_thiele_innes*o.f_thiele_innes))))/o.parallax)/POWER(b.m1*POWER(o.period/365.25,2),1.0/3.0)) AS inferred_m2_mjup
FROM gaiadr3.gaia_source AS g
LEFT OUTER JOIN gaiadr3.nss_two_body_orbit AS o ON o.source_id = g.source_id
LEFT OUTER JOIN gaiadr3.binary_masses AS b ON b.source_id = g.source_id
